sealed class ZkException: kotlin.Exception() {
    
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : ZkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Unsupported(
        
        val `reason`: kotlin.String
        ) : ZkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class ResourceExhausted(
        
        val `reason`: kotlin.String
        ) : ZkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Cancelled(
        ) : ZkException() {
        override val message
            get() = ""
    }
    
    class Internal(
        
        val `code`: kotlin.UInt
        ) : ZkException() {
        override val message
            get() = "code=${ `code` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ZkException> {
        override fun lift(error_buf: RustBuffer.ByValue): ZkException = FfiConverterTypeZkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeZkError : FfiConverterRustBuffer<ZkException> {
    override fun read(buf: ByteBuffer): ZkException {
        

        return when(buf.getInt()) {
            1 -> ZkException.InvalidInput(
                FfiConverterString.read(buf),
                )
            2 -> ZkException.Unsupported(
                FfiConverterString.read(buf),
                )
            3 -> ZkException.ResourceExhausted(
                FfiConverterString.read(buf),
                )
            4 -> ZkException.Cancelled()
            5 -> ZkException.Internal(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ZkException): ULong {
        return when(value) {
            is ZkException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ZkException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ZkException.ResourceExhausted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ZkException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ZkException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`code`)
            )
        }
    }

    override fun write(value: ZkException, buf: ByteBuffer) {
        when(value) {
            is ZkException.InvalidInput -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ZkException.Unsupported -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ZkException.ResourceExhausted -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ZkException.Cancelled -> {
                buf.putInt(4)
                Unit
            }
            is ZkException.Internal -> {
                buf.putInt(5)
                FfiConverterUInt.write(value.`code`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





